package androidx.compose.remote.generator.codegen

import androidx.compose.remote.generator.AstProperty
import androidx.compose.remote.generator.DerivedExpr
import androidx.compose.remote.generator.OperationSchema
import androidx.compose.remote.generator.SchemaBitField
import androidx.compose.remote.generator.SchemaConditionalSkip
import androidx.compose.remote.generator.SchemaField
import androidx.compose.remote.generator.SchemaOperation
import androidx.compose.remote.generator.SchemaSparseParam
import androidx.compose.remote.generator.SchemaStruct
import androidx.compose.remote.generator.SchemaRpnOperatorTable

/**
 * Generator that transforms an [OperationSchema] into idiomatic Swift bindings:
 * - OpCode enum with UInt8 raw values
 * - RemoteOperation protocol
 * - Auxiliary structs and typed structs for each operation with WireBuffer read/write methods
 * - RemoteDocument container and WireBuffer implementation
 */
// LOCAL PATCH (rc-players): one Swift dialect, Swift 6 and the standard library only. Upstream
// emits Foundation (`Data`, `NSError`) and its output does not compile (`min` shadowed by a field);
// rc-players' fork emits `[UInt8]`, a typed `WireError` with typed throws, `Sendable` and
// `Hashable` value types, a closed `WireOperation` enum, and names for every wire value.
internal class SwiftGenerator(private val schema: OperationSchema) {

    private val multiLang = MultiLangProtocolGenerator(schema)

    // LOCAL PATCH (rc-players): constants are named in lowerCamelCase, as Swift's API design
    // guidelines ask, by one rename over the finished file (the templates keep upstream's names).
    fun generate(): String = lowerCamelConstants(generateUpstreamNames())

    private fun generateUpstreamNames(): String = buildCode {
        line("// Generated by RemoteCompose Schema Codegen. DO NOT EDIT.")
        line()
        emitWireError(this)
        line()
        line("/// Operation wire identifiers for RemoteCompose.")
        block("public enum OpCode: UInt8, CaseIterable, Sendable") {
            for (op in schema.operations) {
                val swiftCase = toCamelCase(op.name)
                val desc = op.description.replace("\n", " ").trim()
                if (desc.isNotEmpty()) {
                    line("/// $desc")
                }
                line("case $swiftCase = ${op.id}")
            }
        }
        line()
        line("/// Protocol adopted by all RemoteCompose operation types.")
        block("public protocol RemoteOperation: Sendable") {
            line("var opCode: OpCode { get }")
            line("func write(to buffer: inout WireBuffer) throws(WireError)")
        }
        line()
        emitWireBuffer(this)
        line()
        multiLang.emitSwiftProtocol(this)
        for ((_, structDef) in schema.structs) {
            emitAuxStruct(this, structDef)
            line()
        }
        for (op in schema.operations) {
            emitStruct(this, op)
            line()
        }
        emitRemoteDocument(this)
    }

    // LOCAL PATCH (rc-players): the typed error every read and write throws.
    private fun emitWireError(w: CodeWriter) {
        w.line("/// Why a document or an operation could not be read or written.")
        w.block("public enum WireError: Error, Sendable, Hashable") {
            line("/// The bytes ran out before a value was complete.")
            line("case underflow")
            line("/// A length or count read as negative.")
            line("case invalidLength(type: String, field: String, length: Int)")
            line("/// A length or count is over the field's limit (`WireLimits`).")
            line("case lengthExceedsLimit(type: String, field: String, length: Int, limit: Int)")
            line("/// A length or count is under the field's minimum.")
            line("case lengthBelowMinimum(type: String, field: String, length: Int)")
            line("/// A length or count promises more elements than the bytes left can hold.")
            line("case lengthExceedsBuffer(type: String, field: String, length: Int)")
            line("/// A value is under the field's minimum.")
            line("case valueBelowMinimum(type: String, field: String)")
            line("/// Bits the schema reserves as zero are set.")
            line("case reservedBitsSet(type: String, field: String)")
            line("/// A value is outside a strict enum's values.")
            line("case invalidEnumValue(type: String, field: String)")
            line("/// A field the encoding requires is absent.")
            line("case missingField(type: String, field: String)")
            line("/// A sparse operation carries a parameter id the schema does not define.")
            line("case unknownSparseParameter(type: String, id: Int)")
            line("/// A string's bytes are not valid UTF-8.")
            line("case invalidUTF8")
            line("/// A buffer index outside its bytes.")
            line("case indexOutOfBounds(Int)")
            line("/// The document does not start with a header.")
            line("case expectedHeader")
            line("/// A header appears after the first operation.")
            line("case unexpectedHeader")
            line("/// The header's version word carries neither the modern magic nor a legacy version.")
            line("case invalidHeaderMagic(Int32)")
            line("/// The document declares compression, which these bindings do not read.")
            line("case compressedDocument")
            line("/// An opcode the schema does not define.")
            line("case unknownOpcode(UInt8)")
            line("/// More operations than the reader's limit.")
            line("case operationLimitExceeded(Int)")
            line("/// A packed value ends before a part its flags promise.")
            line("case truncated(type: String, field: String)")
            line("/// A spring animation spec, which `FloatAnimationSpec.unpack` does not read.")
            line("case springAnimationSpec")
        }
        w.line()
        w.line("/// [bytes] as UTF-8 text, or nil when they are not valid UTF-8. The standard library's")
        w.line("/// validating initializer where the platform has it (SE-0405), and a decode-and-compare")
        w.line("/// on the older Apple runtimes this package still supports.")
        w.block("func wireDecodeUTF8(_ bytes: ArraySlice<UInt8>) -> String?") {
            block("if #available(macOS 15, iOS 18, tvOS 18, watchOS 11, visionOS 2, *)") {
                line("return String(validating: bytes, as: UTF8.self)")
            }
            line("let text = String(decoding: bytes, as: UTF8.self)")
            line("return text.utf8.elementsEqual(bytes) ? text : nil")
        }
    }

    private fun emitWireBuffer(w: CodeWriter) {
        w.block("public struct WireBuffer: Sendable") {
            line("public private(set) var data: [UInt8]")
            line("public private(set) var index: Int = 0")
            line()
            block("public init(data: [UInt8] = [])") {
                line("self.data = data")
                line("self.index = 0")
            }
            line()
            block("public var remaining: Int") { line("return max(0, data.count - index)") }
            line()
            block("public var available: Bool") { line("return index < data.count") }
            line()
            block("public mutating func setIndex(_ newIndex: Int) throws(WireError)") {
                block("guard newIndex >= 0 && newIndex <= data.count else") {
                    line(
                        "throw WireError.indexOutOfBounds(newIndex)"
                    )
                }
                line("index = newIndex")
            }
            line()
            block("public mutating func skipBytes(_ count: Int) throws(WireError)") {
                block("guard count >= 0 else") {
                    line(
                        "throw WireError.invalidLength(type: \"WireBuffer\", field: \"skip\", length: count)"
                    )
                }
                block("guard count <= remaining else") {
                    line(
                        "throw WireError.underflow"
                    )
                }
                line("index += count")
            }
            line()
            block("public mutating func writeByte(_ value: UInt8)") { line("data.append(value)") }
            line()
            block("public mutating func readByte() throws(WireError) -> UInt8") {
                block("guard 1 <= remaining else") {
                    line(
                        "throw WireError.underflow"
                    )
                }
                line("let byte = data[index]")
                line("index += 1")
                line("return byte")
            }
            line()
            block("public mutating func writeShort(_ value: Int16)") {
                line("var val = value.bigEndian")
                line("withUnsafeBytes(of: &val) { data.append(contentsOf: \$0) }")
            }
            line()
            // LOCAL PATCH (rc-players): one big-endian reader, sized by the type it reads, so no byte
            // count or shift is written as a number.
            block(
                "private mutating func readBigEndian<T: FixedWidthInteger & UnsignedInteger>(_ type: T.Type) throws(WireError) -> T"
            ) {
                line("let size = MemoryLayout<T>.size")
                block("guard size <= remaining else") {
                    line(
                        "throw WireError.underflow"
                    )
                }
                line("var bits: T = 0")
                block("for offset in 0..<size") {
                    line("bits = (bits << UInt8.bitWidth) | T(data[index + offset])")
                }
                line("index += size")
                line("return bits")
            }
            line()
            block("public mutating func readShort() throws(WireError) -> Int16") {
                line("return Int16(bitPattern: try readBigEndian(UInt16.self))")
            }
            line()
            block("public mutating func writeInt(_ value: Int32)") {
                line("var val = value.bigEndian")
                line("withUnsafeBytes(of: &val) { data.append(contentsOf: \$0) }")
            }
            line()
            block("public mutating func readInt() throws(WireError) -> Int32") {
                line("return Int32(bitPattern: try readBigEndian(UInt32.self))")
            }
            line()
            block("public mutating func writeLong(_ value: Int64)") {
                line("var val = value.bigEndian")
                line("withUnsafeBytes(of: &val) { data.append(contentsOf: \$0) }")
            }
            line()
            block("public mutating func readLong() throws(WireError) -> Int64") {
                line("return Int64(bitPattern: try readBigEndian(UInt64.self))")
            }
            line()
            block("public mutating func writeFloat(_ value: Float)") {
                line("var bitVal = value.bitPattern.bigEndian")
                line("withUnsafeBytes(of: &bitVal) { data.append(contentsOf: \$0) }")
            }
            line()
            block("public mutating func readFloat() throws(WireError) -> Float") {
                line("let bitVal = UInt32(bitPattern: try readInt())")
                line("return Float(bitPattern: bitVal)")
            }
            line()
            block("public mutating func writeBoolean(_ value: Bool)") {
                line("writeByte(value ? 1 : 0)")
            }
            line()
            block("public mutating func readBoolean() throws(WireError) -> Bool") {
                line("return (try readByte()) != 0")
            }
            line()
            block("public mutating func writeUTF8(_ value: String)") {
                line("writeInt(Int32(value.utf8.count))")
                line("data.append(contentsOf: value.utf8)")
            }
            line()
            block("public mutating func readUTF8(maxLength: Int? = nil) throws(WireError) -> String") {
                line("let len = Int(try readInt())")
                block("guard len >= 0 else") {
                    line(
                        "throw WireError.invalidLength(type: \"WireBuffer\", field: \"utf8\", length: len)"
                    )
                }
                block("if let maxLen = maxLength, len > maxLen") {
                    line(
                        "throw WireError.lengthExceedsLimit(type: \"WireBuffer\", field: \"utf8\", length: len, limit: maxLen)"
                    )
                }
                block("guard len <= remaining else") {
                    line(
                        "throw WireError.underflow"
                    )
                }
                block("guard let str = wireDecodeUTF8(data[index..<(index + len)]) else") {
                    line(
                        "throw WireError.invalidUTF8"
                    )
                }
                line("index += len")
                line("return str")
            }
            line()
            block("public mutating func writeBuffer(_ value: [UInt8])") {
                line("writeInt(Int32(value.count))")
                line("data.append(contentsOf: value)")
            }
            line()
            block("public mutating func writeBytes(_ value: [UInt8])") {
                line("data.append(contentsOf: value)")
            }
            line()
            block("public mutating func readBytes(count: Int) throws(WireError) -> [UInt8]") {
                block("guard count >= 0 else") {
                    line(
                        "throw WireError.invalidLength(type: \"WireBuffer\", field: \"bytes\", length: count)"
                    )
                }
                block("guard count <= remaining else") {
                    line(
                        "throw WireError.underflow"
                    )
                }
                line("let bufData = Array(data[index..<(index + count)])")
                line("index += count")
                line("return bufData")
            }
            line()
            block("public mutating func readBuffer(maxLength: Int? = nil) throws(WireError) -> [UInt8]") {
                line("let len = Int(try readInt())")
                block("guard len >= 0 else") {
                    line(
                        "throw WireError.invalidLength(type: \"WireBuffer\", field: \"buffer\", length: len)"
                    )
                }
                block("if let maxLen = maxLength, len > maxLen") {
                    line(
                        "throw WireError.lengthExceedsLimit(type: \"WireBuffer\", field: \"buffer\", length: len, limit: maxLen)"
                    )
                }
                block("guard len <= remaining else") {
                    line(
                        "throw WireError.underflow"
                    )
                }
                line("let bufData = Array(data[index..<(index + len)])")
                line("index += len")
                line("return bufData")
            }
        }
    }

    // LOCAL PATCH (rc-players): every wire value the templates below write is named. Upstream
    // writes limits, element sizes, sparse-parameter ids, enum values and bit layouts as numbers;
    // these name them from the schema, so the generated Swift carries no wire magic numbers.

    /** The `WireLimits` name of each field's `maxLength`: its `javaLimit`, or one made for it. */
    private val limits: Pair<Map<SchemaField, String>, Map<String, Int>> by lazy {
        val names = HashMap<SchemaField, String>()
        val values = linkedMapOf<String, Int>()
        fun add(owner: String, f: SchemaField) {
            val max = f.maxLength ?: return
            val own = "${constName(owner)}_${constName(f.name)}_MAX_LENGTH"
            // A `javaLimit` that is an expression (`Limits.X * 2`) is not a name: the field gets one.
            var name =
                f.javaLimit
                    ?.removePrefix("Limits.")
                    ?.takeIf { it.matches(Regex("[A-Z_][A-Z0-9_]*")) } ?: own
            if (values[name]?.let { it != max } == true) name = own
            values[name] = max
            names[f] = name
        }
        schema.operations.forEach { op -> op.fields.forEach { add(op.name, it) } }
        schema.structs.values.forEach { st -> st.fields.forEach { add(st.name, it) } }
        names to values
    }

    private fun limitRef(f: SchemaField): String? = limits.first[f]?.let { "WireLimits.$it" }

    private fun constName(name: String): String = CodegenExprUtils.toSnakeCase(name).uppercase()

    private fun emitWireLimits(w: CodeWriter) {
        w.line("/// The reader's limits, by name: each field's `maxLength` (`Limits.*` where AndroidX")
        w.line("/// names it).")
        w.block("public enum WireLimits") {
            for ((name, value) in limits.second.entries.sortedBy { it.key }) {
                line("public static let $name: Int = $value")
            }
            line("/// The most elements an array read reserves room for before it has read them.")
            line("public static let MAX_INITIAL_CAPACITY: Int = $MAX_INITIAL_CAPACITY")
        }
        w.line()
    }

    /** The fewest bytes one element of [elemType] takes on the wire, as Swift computes it. */
    private fun elementBytes(elemType: String): String =
        when (elemType) {
            "int", "int_id", "color", "float", "float_or_id", "string", "bytes" ->
                "MemoryLayout<Int32>.size"
            "short" -> "MemoryLayout<Int16>.size"
            "byte", "boolean" -> "MemoryLayout<UInt8>.size"
            "long" -> "MemoryLayout<Int64>.size"
            else ->
                if (schema.structs.containsKey(elemType)) "$elemType.MIN_WIRE_BYTES"
                else "MemoryLayout<Int32>.size"
        }

    /** A sparse key's size: a sparse entry is a key and at least one byte of value. */
    private fun sparseKeyBytes(keyType: String): String =
        when (keyType) {
            "int" -> "MemoryLayout<Int32>.size"
            "short", "ushort" -> "MemoryLayout<Int16>.size"
            else -> "MemoryLayout<UInt8>.size"
        }

    /** [name] = [value] as the owner's own enum constant, which the struct emits by that name. */
    private fun enumRef(ownerName: String, fields: List<SchemaField>, name: String, value: Int): String {
        val constants = multiLang.collectEnumConstants(fields).toMap()
        check(constants[name] == value) { "$ownerName.$name is not the constant $value" }
        return "$ownerName.$name"
    }

    private fun ownerFields(ownerName: String): List<SchemaField> =
        schema.operationsByName[ownerName]?.fields
            ?: schema.structs[ownerName]?.fields
            ?: error("no operation or struct $ownerName")

    private fun bitBase(field: String, bit: String): String =
        field + bit.replaceFirstChar { it.uppercaseChar() }

    private fun hex(value: Long): String = "0x" + value.toString(16).uppercase()

    /** The `BitLayout` constants of [fields]' bit ranges, reserved bits and skip condition. */
    private fun emitBitLayout(w: CodeWriter, fields: List<SchemaField>, skip: SchemaConditionalSkip?) {
        val out = linkedMapOf<String, String>()
        fun range(base: String, b: SchemaBitField) {
            if (b.bitWidth >= 32) return
            out["${base}Shift"] = "${b.lowBit}"
            out["${base}Mask"] = hex(b.bitMask)
            if (b.signed) {
                out["${base}LeftShift"] = "${31 - b.highBit}"
                out["${base}RightShift"] = "${31 - b.highBit + b.lowBit}"
            }
        }
        fun bit(field: String, b: SchemaBitField) {
            val base = bitBase(field, b.name)
            range(base, b)
            b.whenBitSet?.let { c ->
                out["${base}NarrowFlagShift"] = "${c.bit}"
                range("${base}Narrow", SchemaBitField(name = b.name, range = c.range, signed = false))
            }
        }
        for (f in fields) {
            f.bits?.forEach { bit(f.name, it) }
            f.mustBeZeroBits?.let { r ->
                val low = r.substringBefore("..").toInt()
                val high = r.substringAfter("..", r).toInt()
                val width = high - low + 1
                val mask = if (width >= 32) 0xFFFFFFFFL else ((1L shl width) - 1L) shl low
                out["${f.name}ReservedMask"] = hex(mask)
            }
        }
        skip?.let { bit(it.conditionField, skipBit(it)) }
        if (out.isEmpty()) return
        w.line("/// The shifts and masks of this type's packed fields, from the schema's bit ranges.")
        w.block("public enum BitLayout") {
            for ((name, value) in out) line("public static let $name: UInt32 = $value")
        }
    }

    private fun skipBit(cs: SchemaConditionalSkip): SchemaBitField =
        SchemaBitField(name = "condition", range = cs.conditionBits, signed = cs.conditionSigned)

    /** [bit] of [field] read out of [src], as `CodegenExprUtils.extractBitExpr` does, by name. */
    private fun swiftExtract(src: String, field: String, bit: SchemaBitField): String {
        val base = bitBase(field, bit.name)
        val normal = swiftExtractRange(src, base, bit)
        val c = bit.whenBitSet ?: return normal
        val narrow =
            swiftExtractRange(src, "${base}Narrow", SchemaBitField(name = bit.name, range = c.range))
        return "(((UInt32(bitPattern: $src) >> BitLayout.${base}NarrowFlagShift) & 1) != 0 ? $narrow : $normal)"
    }

    private fun swiftExtractRange(src: String, base: String, b: SchemaBitField): String {
        if (b.bitWidth >= 32) return src
        return if (b.signed) {
            "(Int32(bitPattern: UInt32(bitPattern: $src) << BitLayout.${base}LeftShift) >> BitLayout.${base}RightShift)"
        } else {
            "Int32((UInt32(bitPattern: $src) >> BitLayout.${base}Shift) & BitLayout.${base}Mask)"
        }
    }

    private fun swiftPack(field: String, terms: List<Pair<String, SchemaBitField>>): String {
        if (terms.isEmpty()) return "0"
        return "Int32(bitPattern: " +
            terms.joinToString(" | ") { (v, b) ->
                val base = bitBase(field, b.name)
                "((UInt32(bitPattern: Int32($v)) & BitLayout.${base}Mask) << BitLayout.${base}Shift)"
            } + ")"
    }

    private fun swiftReservedBits(src: String, field: String): String =
        "((UInt32(bitPattern: Int32($src)) & BitLayout.${field}ReservedMask) != 0)"

    // LOCAL PATCH (rc-players): a field's schema default by name, `<Owner>.DEFAULT_<FIELD>`.
    private val numericTypes =
        setOf("int", "int_id", "color", "short", "byte", "long", "float", "float_or_id")

    private fun defaultFields(fields: List<SchemaField>): List<SchemaField> =
        fields.filter { it.defaultValue != null && it.type in numericTypes }

    private fun defaultRef(owner: String, f: SchemaField): String = "$owner.DEFAULT_${constName(f.name)}"

    private fun emitDefaults(w: CodeWriter, fields: List<SchemaField>) {
        for (f in defaultFields(fields)) {
            w.line(
                "public static let DEFAULT_${constName(f.name)}: ${mapToSwiftType(f.type, false)} = ${mapToSwiftDefault(f.type, false, f.defaultValue)}"
            )
        }
    }

    private fun initDefault(owner: String, fields: List<SchemaField>, prop: AstProperty): String {
        val f = defaultFields(fields).firstOrNull { it.name == prop.name }
        return if (f != null && !prop.isNullable) defaultRef(owner, f)
        else mapToSwiftDefault(prop.type, prop.isNullable, prop.defaultValue)
    }

    // LOCAL PATCH (rc-players): a condition with every value named. Upstream copies the schema's
    // expression into Swift as it stands, numbers and all; the fork's schema names them, and Swift
    // reads them from [WIRE_EXPRESSION_CONSTANTS]. The fields are widened to `Int` so one constant
    // compares with a `UInt8`, an `Int16` or an `Int32` field alike.
    private fun swiftCondition(expr: String): String =
        // A bare name is a `Bool` the read computed (`skipTaken`): it is the condition as it stands.
        if (expr.trim().matches(Regex("[A-Za-z_][A-Za-z0-9_]*"))) expr.trim()
        else CodegenExprUtils.translateCondition(
            expr,
            ExprLang.SWIFT,
            constants = schema.conditionConstants.keys.associateWith { "$WIRE_EXPRESSION_CONSTANTS.$it" },
        ) {
            "Int($it)"
        }

    // LOCAL PATCH (rc-players): the constants [swiftCondition] names, from the schema.
    private fun emitWireExpressionConstants(w: CodeWriter) {
        if (schema.conditionConstants.isEmpty()) return
        w.line("/// Named values the schema defines outside any one field: its `expressionConstants` (the")
        w.line("/// values its field conditions compare against, and component visibility) and its header")
        w.line("/// constants.")
        w.block("public enum $WIRE_EXPRESSION_CONSTANTS") {
            for ((name, value) in schema.conditionConstants) {
                line("public static let $name: Int = $value")
            }
        }
        w.line()
    }

    // LOCAL PATCH (rc-players): the schema's operator tables, so a writer names every operator
    // word it emits. Upstream's Swift has no writer and leaves them out.
    private fun emitOperatorTable(w: CodeWriter, table: SchemaRpnOperatorTable?, name: String, reader: String) {
        if (table == null) return
        w.line("/// $reader's operators. An operator is written as the word whose id is `offset` plus")
        w.line("/// its code, NaN-boxed as an id is.")
        w.block("public enum $name") {
            line("public static let OFFSET: Int32 = ${table.offset}")
            for (op in table.operators.sortedBy { it.id }) {
                line("/// ${op.description.ifEmpty { op.name }}")
                line("public static let ${op.name}: Int32 = ${op.id}")
            }
        }
        w.line()
    }

    // LOCAL PATCH (rc-players): the header's bit layout and limits, derived from the schema, so the
    // loader below names every wire value instead of repeating it as a literal.
    private fun emitHeaderLayout(w: CodeWriter) {
        fun bits(fields: List<SchemaField>?, field: String, bit: String): SchemaBitField =
            checkNotNull(fields?.firstOrNull { it.name == field }?.bits?.firstOrNull { it.name == bit }) {
                "the schema does not describe $field.$bit"
            }
        fun range(b: SchemaBitField): IntRange =
            b.range.split("..").let { it[0].toInt()..it.last().toInt() }
        fun mask(b: SchemaBitField): Long =
            range(b).fold(0L) { acc, i -> acc or (1L shl i) }
        val header = schema.operationsByName.getValue("Header").fields
        val tag = schema.structs.getValue("HeaderProperty").fields
        val version = bits(header, "majorVersion", "version")
        val magic = bits(header, "majorVersion", "magic")
        val key = bits(tag, "tag", "key")
        val dataType = bits(tag, "tag", "dataType")
        val defaultSize = checkNotNull(header.first { it.name == "width" }.defaultValue)
        val maxString = schema.operationsByName.getValue("TextData").fields
            .first { it.name == "text" }.maxLength.let { checkNotNull(it) { "TextData.text has no maxLength" } }
        for (name in listOf("DATA_TYPE_INT", "DATA_TYPE_FLOAT", "DATA_TYPE_LONG", "DATA_TYPE_STRING", "MAGIC_NUMBER")) {
            check(schema.headerConstants.values.any { name in it }) { "headerConstants has no $name" }
        }
        w.line("/// A header's bit layout and limits, from the schema: the major-version word (version and")
        w.line("/// magic) and each property's tag (key and data type).")
        w.block("public enum HeaderLayout") {
            line("public static let versionMask: Int32 = 0x${mask(version).toString(16).uppercase()}")
            line("public static let magicMask: UInt32 = 0x${mask(magic).toString(16).uppercase()}")
            line("public static let propertyKeyMask: Int32 = 0x${mask(key).toString(16).uppercase()}")
            line("public static let propertyTypeShift: Int32 = ${range(dataType).first}")
            line("/// The width and height a modern header without size properties declares.")
            line("public static let defaultSize: Int32 = $defaultSize")
            line("/// The longest string property a header may carry.")
            line("public static let maxStringLength: Int = $maxString")
        }
        w.line()
    }

    // LOCAL PATCH (rc-players): a closed `WireOperation` enum in place of `[RemoteOperation]`
    // existentials, and `WireDocument` (upstream: `RemoteDocument`, which clashed with the authoring
    // API's) keeping a modern header's properties so it writes back what it read.
    private fun emitRemoteDocument(w: CodeWriter) {
        emitWireExpressionConstants(w)
        emitOperatorTable(w, schema.rpnOperators, "FloatExpressionOperator", "`FloatExpression`")
        emitOperatorTable(w, schema.intRpnOperators, "IntegerExpressionOperator", "`IntegerExpression`")
        emitWireLimits(w)
        emitHeaderLayout(w)
        val bodyOps = schema.operations.filter { it.name != "Header" }
        w.line("/// One operation of a document, by kind. The set is closed, so a `switch` over it is")
        w.line("/// exhaustive and no operation needs a downcast.")
        w.block("public enum WireOperation: Sendable, Hashable") {
            for (op in bodyOps) line("case ${toCamelCase(op.name)}(${op.name})")
            line()
            block("public var opCode: OpCode") {
                swiftSwitch("self") {
                    for (op in bodyOps) line("case .${toCamelCase(op.name)}: return .${toCamelCase(op.name)}")
                }
            }
            line()
            line("/// Writes this operation, opcode first.")
            block("public func write(to buffer: inout WireBuffer) throws(WireError)") {
                swiftSwitch("self") {
                    for (op in bodyOps) {
                        line("case .${toCamelCase(op.name)}(let operation): try operation.write(to: &buffer)")
                    }
                }
            }
            line()
            block(
                "static func read(_ opCode: OpCode, from buffer: inout WireBuffer, evaluateSkip: Bool, playerApiLevel: Int32, playerProfiles: Int32) throws(WireError) -> WireOperation"
            ) {
                swiftSwitch("opCode") {
                    for (op in schema.operations) {
                        val c = toCamelCase(op.name)
                        swiftCase("case .$c") {
                            if (op.name == "Header") {
                                line("throw WireError.unexpectedHeader")
                            } else if (op.conditionalSkip != null) {
                                line(
                                    "return .$c(evaluateSkip ? try ${op.name}.readForPlayer(from: &buffer, playerApiLevel: playerApiLevel, playerProfiles: playerProfiles) : try ${op.name}.read(from: &buffer))"
                                )
                            } else {
                                line("return .$c(try ${op.name}.read(from: &buffer))")
                            }
                        }
                    }
                }
            }
        }
        w.line()
        w.line("/// A Remote Compose document: its header and its operations.")
        w.block("public struct WireDocument: Sendable, Hashable") {
            line("public static let maxHeaderProperties: Int = 1000")
            line("public static let maxOperationCount: Int = 100_000")
            line()
            line("public var majorVersion: Int32")
            line("public var minorVersion: Int32")
            line("public var patchVersion: Int32")
            line("/// A modern header's properties, in the order read and written; nil for a legacy header.")
            line("public var properties: [HeaderProperty]?")
            line("/// The document's size: a legacy header's fields, or a modern header's size properties.")
            line("public var width: Int32")
            line("public var height: Int32")
            line("/// The profile bits: a legacy header's field, or a modern header's profiles property.")
            line("public var capabilities: Int64")
            line("public var operations: [WireOperation]")
            line()
            block(
                "public init(majorVersion: Int32 = HeaderConstants.MAJOR_VERSION, minorVersion: Int32 = HeaderConstants.MINOR_VERSION, patchVersion: Int32 = HeaderConstants.PATCH_VERSION, properties: [HeaderProperty]? = nil, width: Int32 = HeaderLayout.defaultSize, height: Int32 = HeaderLayout.defaultSize, capabilities: Int64 = 0, operations: [WireOperation] = [])"
            ) {
                line("self.majorVersion = majorVersion")
                line("self.minorVersion = minorVersion")
                line("self.patchVersion = patchVersion")
                line("self.properties = properties")
                line("self.width = width")
                line("self.height = height")
                line("self.capabilities = capabilities")
                line("self.operations = operations")
            }
            line()
            line("/// Reads a document from its bytes.")
            block(
                "public static func load(from bytes: [UInt8], maxOperations: Int = maxOperationCount) throws(WireError) -> WireDocument"
            ) {
                line(
                    "return try loadImpl(from: bytes, maxOperations: maxOperations, evaluateSkip: false, playerApiLevel: 0, playerProfiles: 0)"
                )
            }
            line()
            line("/// Reads a document, evaluating its conditional skips against the target player.")
            block(
                "public static func loadForPlayer(from bytes: [UInt8], playerApiLevel: Int32, playerProfiles: Int32 = 0, maxOperations: Int = maxOperationCount) throws(WireError) -> WireDocument"
            ) {
                line(
                    "return try loadImpl(from: bytes, maxOperations: maxOperations, evaluateSkip: true, playerApiLevel: playerApiLevel, playerProfiles: playerProfiles)"
                )
            }
            line()
            block(
                "private static func loadImpl(from bytes: [UInt8], maxOperations: Int, evaluateSkip: Bool, playerApiLevel: Int32, playerProfiles: Int32) throws(WireError) -> WireDocument"
            ) {
                line("var buffer = WireBuffer(data: bytes)")
                line("var doc = WireDocument()")
                line("guard buffer.available else { return doc }")
                block("guard try buffer.readByte() == OpCode.header.rawValue else") {
                    line("throw WireError.expectedHeader")
                }
                line("let rawMajor = try buffer.readInt()")
                line("doc.minorVersion = try buffer.readInt()")
                line("doc.patchVersion = try buffer.readInt()")
                block(
                    "if (UInt32(bitPattern: rawMajor) & HeaderLayout.magicMask) == UInt32(bitPattern: HeaderConstants.MAGIC_NUMBER)",
                    close = null,
                ) {
                    line("doc.majorVersion = rawMajor & HeaderLayout.versionMask")
                    line("let numProps = Int(try buffer.readInt())")
                    block("guard numProps >= 0 && numProps <= maxHeaderProperties else") {
                        line("throw WireError.invalidLength(type: \"Header\", field: \"properties\", length: numProps)")
                    }
                    block("guard numProps <= buffer.remaining / HeaderProperty.MIN_WIRE_BYTES else") {
                        line(
                            "throw WireError.lengthExceedsBuffer(type: \"Header\", field: \"properties\", length: numProps)"
                        )
                    }
                    line("var properties: [HeaderProperty] = []")
                    line("properties.reserveCapacity(numProps)")
                    block("for _ in 0..<numProps") {
                        line("let property = try HeaderProperty.read(from: &buffer)")
                        line("let key = Int32(property.tag) & HeaderLayout.propertyKeyMask")
                        line("let value = property.intValue.map(Int64.init) ?? property.longValue")
                        block("if key == HeaderProperty.COMPRESS, let value, value != 0") {
                            line("throw WireError.compressedDocument")
                        }
                        line("if key == HeaderProperty.DOC_WIDTH, let width = property.intValue { doc.width = width }")
                        line("if key == HeaderProperty.DOC_HEIGHT, let height = property.intValue { doc.height = height }")
                        line(
                            "if key == HeaderProperty.DOC_PROFILES, let value { doc.capabilities = property.intValue.map { Int64(UInt32(bitPattern: $0)) } ?? value }"
                        )
                        line("properties.append(property)")
                    }
                    line("doc.properties = properties")
                }
                block("} else if rawMajor >= 0 && rawMajor <= HeaderLayout.versionMask", close = null) {
                    line("doc.majorVersion = rawMajor")
                    line("doc.width = try buffer.readInt()")
                    line("doc.height = try buffer.readInt()")
                    line("doc.capabilities = try buffer.readLong()")
                }
                block("} else") { line("throw WireError.invalidHeaderMagic(rawMajor)") }
                line()
                block("while buffer.available") {
                    block("guard doc.operations.count < maxOperations else") {
                        line("throw WireError.operationLimitExceeded(maxOperations)")
                    }
                    line("let opByte = try buffer.readByte()")
                    block("guard let opCode = OpCode(rawValue: opByte) else") {
                        line("throw WireError.unknownOpcode(opByte)")
                    }
                    line(
                        "doc.operations.append(try WireOperation.read(opCode, from: &buffer, evaluateSkip: evaluateSkip, playerApiLevel: playerApiLevel, playerProfiles: playerProfiles))"
                    )
                }
                line("return doc")
            }
            line()
            line("/// The document's bytes: the header as it was read (modern with its properties, or")
            line("/// legacy), then every operation.")
            block("public func save() throws(WireError) -> [UInt8]") {
                line("var buffer = WireBuffer()")
                line("buffer.writeByte(OpCode.header.rawValue)")
                block("if let properties", close = null) {
                    line("buffer.writeInt(HeaderConstants.MAGIC_NUMBER | (majorVersion & HeaderLayout.versionMask))")
                    line("buffer.writeInt(minorVersion)")
                    line("buffer.writeInt(patchVersion)")
                    line("buffer.writeInt(Int32(properties.count))")
                    line("for property in properties { try property.write(to: &buffer) }")
                }
                block("} else") {
                    line("buffer.writeInt(majorVersion)")
                    line("buffer.writeInt(minorVersion)")
                    line("buffer.writeInt(patchVersion)")
                    line("buffer.writeInt(width)")
                    line("buffer.writeInt(height)")
                    line("buffer.writeLong(capabilities)")
                }
                block("for operation in operations") { line("try operation.write(to: &buffer)") }
                line("return buffer.data")
            }
        }
    }

    private fun emitAuxStruct(w: CodeWriter, structDef: SchemaStruct) {
        val props = structDef.astProperties
        val desc = structDef.description.replace("\n", " ").trim()
        if (desc.isNotEmpty()) {
            w.line("/// $desc")
        }
        w.block("public struct ${structDef.name}: Sendable, Hashable") {
            multiLang.emitSwiftOpEnumConstants(this, structDef.fields)
            // LOCAL PATCH (rc-players): named sizes and bit layouts.
            line(
                "public static let MIN_WIRE_BYTES: Int = ${CodegenExprUtils.minWireElementBytes(structDef.name, schema)}"
            )
            emitBitLayout(this, structDef.fields, null)
            emitDefaults(this, structDef.fields)
            for (prop in props) {
                val swiftType = mapToSwiftType(prop.type, prop.isNullable)
                val fieldDesc = prop.description.replace("\n", " ").trim()
                if (fieldDesc.isNotEmpty()) {
                    line("/// $fieldDesc")
                }
                line("public var ${prop.name}: $swiftType")
            }
            val structByteOrShort =
                structDef.fields
                    .filter { it.type == "byte" || it.type == "short" }
                    .map { it.name }
                    .toSet()
            val structNullable = props.filter { it.isNullable }.map { it.name }.toSet()
            for ((fieldName, bit) in structDef.computedBitProperties) {
                if (fieldName in structNullable) {
                    val srcExpr = if (fieldName in structByteOrShort) "Int32(\$0)" else "\$0"
                    block("public var ${bit.name}: Int32?") {
                        line(
                            "return $fieldName.map { ${swiftExtract(srcExpr, fieldName, bit)} }"
                        )
                    }
                } else {
                    val srcExpr =
                        if (fieldName in structByteOrShort) "Int32($fieldName)" else fieldName
                    block("public var ${bit.name}: Int32") {
                        line(
                            "return ${swiftExtract(srcExpr, fieldName, bit)}"
                        )
                    }
                }
            }
            line()

            val params =
                props.joinToString(", ") {
                    "${it.name}: ${mapToSwiftType(it.type, it.isNullable)} = ${initDefault(structDef.name, structDef.fields, it)}"
                }
            block("public init($params)") {
                for (prop in props) {
                    line("self.${prop.name} = ${prop.name}")
                }
            }
            line()

            block(
                "public static func read(from buffer: inout WireBuffer) throws(WireError) -> ${structDef.name}"
            ) {
                emitSwiftReadBody(this, structDef.name, structDef.fields, null, props)
            }
            line()

            block("public func write(to buffer: inout WireBuffer) throws(WireError)") {
                emitSwiftWriteBody(this, structDef.name, structDef.fields, null, props)
            }
        }
    }

    private fun emitStruct(w: CodeWriter, op: SchemaOperation) {
        val props = op.astProperties
        val desc = op.description.replace("\n", " ").trim()
        if (desc.isNotEmpty()) {
            w.line("/// $desc")
        }
        val swiftCase = toCamelCase(op.name)
        w.block("public struct ${op.name}: RemoteOperation, Hashable") {
            line("public let opCode: OpCode = .$swiftCase")
            multiLang.emitSwiftOpEnumConstants(this, op.fields)
            // LOCAL PATCH (rc-players): named bit layouts and sparse-parameter ids.
            emitBitLayout(this, op.fields, op.conditionalSkip)
            emitDefaults(this, op.fields)
            op.sparseParameters?.takeIf { it.isNotEmpty() }?.let { params ->
                block("public enum SparseParameterID") {
                    for (sp in params) line("public static let ${sp.name}: Int = ${sp.id}")
                }
            }
            line()

            for (prop in props) {
                val swiftType = mapToSwiftType(prop.type, prop.isNullable)
                val fieldDesc = prop.description.replace("\n", " ").trim()
                if (fieldDesc.isNotEmpty()) {
                    line("/// $fieldDesc")
                }
                line("public var ${prop.name}: $swiftType")
            }
            val opByteOrShort =
                op.fields.filter { it.type == "byte" || it.type == "short" }.map { it.name }.toSet()
            val opNullable = props.filter { it.isNullable }.map { it.name }.toSet()
            for ((fieldName, bit) in op.computedBitProperties) {
                if (fieldName in opNullable) {
                    val srcExpr = if (fieldName in opByteOrShort) "Int32(\$0)" else "\$0"
                    block("public var ${bit.name}: Int32?") {
                        line(
                            "return $fieldName.map { ${swiftExtract(srcExpr, fieldName, bit)} }"
                        )
                    }
                } else {
                    val srcExpr = if (fieldName in opByteOrShort) "Int32($fieldName)" else fieldName
                    block("public var ${bit.name}: Int32") {
                        line(
                            "return ${swiftExtract(srcExpr, fieldName, bit)}"
                        )
                    }
                }
            }
            multiLang.emitSwiftOpExtras(this, op)
            line()

            val params =
                props.joinToString(", ") {
                    "${it.name}: ${mapToSwiftType(it.type, it.isNullable)} = ${initDefault(op.name, op.fields, it)}"
                }
            line("/// Creates a new [${op.name}] operation.")
            if (props.isNotEmpty()) {
                line("/// - Parameters:")
                for (prop in props) {
                    val fieldDesc = prop.description.replace("\n", " ").trim()
                    line("///   - ${prop.name}: $fieldDesc")
                }
            }
            block("public init($params)") {
                for (prop in props) {
                    line("self.${prop.name} = ${prop.name}")
                }
            }
            line()

            line("/// Reads and decodes a [${op.name}] from the wire buffer.")
            block("public static func read(from buffer: inout WireBuffer) throws(WireError) -> ${op.name}") {
                if (op.conditionalSkip != null) {
                    line("let skipTaken = true")
                }
                emitSwiftReadBody(
                    this,
                    op.name,
                    op.fields,
                    op.sparseParameters,
                    props,
                    op.sparseCountType,
                    op.sparseKeyType,
                )
            }
            line()

            if (op.conditionalSkip != null) {
                val cs = op.conditionalSkip
                val condExpr =
                    swiftExtract(cs.conditionField, cs.conditionField, skipBit(cs))
                block(
                    "public static func shouldSkip(${cs.conditionField}: Int32, ${cs.valueField}: Int32, playerApiLevel: Int32, playerProfiles: Int32) -> Bool"
                ) {
                    swiftSwitch(condExpr) {
                        for (b in cs.conditions) {
                            val brExpr =
                                CodegenExprUtils.evaluateSkipBranchExpr(
                                    b,
                                    cs.valueField,
                                    "playerApiLevel",
                                    "playerProfiles",
                                    ExprLang.SWIFT,
                                )
                            line(
                                "case ${enumRef(op.name, op.fields, b.name, b.whenValue)}: return $brExpr"
                            )
                        }
                        line("default: return ${cs.unknownConditionSkips}")
                    }
                }
                line()
                block(
                    "public static func readForPlayer(from buffer: inout WireBuffer, playerApiLevel: Int32, playerProfiles: Int32 = 0) throws(WireError) -> ${op.name}"
                ) {
                    emitSwiftReadBody(
                        this,
                        op.name,
                        op.fields,
                        op.sparseParameters,
                        props,
                        op.sparseCountType,
                        op.sparseKeyType,
                        conditionalSkip = cs,
                    )
                }
                line()
            }

            line("/// Serializes this operation to the wire buffer.")
            block("public func write(to buffer: inout WireBuffer) throws(WireError)") {
                line("buffer.writeByte(opCode.rawValue)")
                emitSwiftWriteBody(
                    this,
                    op.name,
                    op.fields,
                    op.sparseParameters,
                    props,
                    op.sparseCountType,
                    op.sparseKeyType,
                    op.conditionalSkip,
                )
            }
        }
    }

    private fun hasSwiftScalarValidations(f: SchemaField): Boolean {
        if (f.minValue != null) return true
        if (f.mustBeZeroBits != null) return true
        if (f.strictEnum && !f.enumValues.isNullOrEmpty()) return true
        val bits = f.bits
        return bits != null &&
            !f.unpackBits &&
            bits.any { it.strictEnum && !it.enumValues.isNullOrEmpty() }
    }

    private fun emitSwiftScalarValidations(
        w: CodeWriter,
        ownerName: String,
        f: SchemaField,
        varExpr: String,
    ) {
        val intExpr = if (f.type == "byte" || f.type == "short") "Int32($varExpr)" else varExpr
        if (f.minValue != null) {
            w.block("guard $intExpr >= ${f.minValue} else") {
                line(
                    "throw WireError.valueBelowMinimum(type: \"$ownerName\", field: \"${f.name}\")"
                )
            }
        }
        if (f.mustBeZeroBits != null) {
            val badBits = swiftReservedBits(intExpr, f.name)
            w.block("if $badBits") {
                line(
                    "throw WireError.reservedBitsSet(type: \"$ownerName\", field: \"${f.name}\")"
                )
            }
        }
        emitSwiftStrictEnumCheck(w, ownerName, f.name, varExpr, f.strictEnum, f.enumValues)
        val bits = f.bits
        if (bits != null && !f.unpackBits) {
            for (b in bits) {
                if (b.strictEnum && !b.enumValues.isNullOrEmpty()) {
                    val bVar = "bit_${b.name}"
                    val extract = swiftExtract(intExpr, f.name, b)
                    w.line("let $bVar = $extract")
                    emitSwiftStrictEnumCheck(
                        w,
                        ownerName,
                        b.name,
                        bVar,
                        b.strictEnum,
                        b.enumValues,
                    )
                }
            }
        }
    }

    private fun emitSwiftReadBody(
        w: CodeWriter,
        ownerName: String,
        fields: List<SchemaField>,
        sparseParameters: List<SchemaSparseParam>?,
        props: List<AstProperty>,
        sparseCountType: String? = null,
        sparseKeyType: String? = null,
        conditionalSkip: SchemaConditionalSkip? = null,
    ) {
        for (f in fields) {
            if (conditionalSkip != null && f.name == conditionalSkip.payloadField) {
                w.line(
                    "let skipTaken = shouldSkip(${conditionalSkip.conditionField}: ${conditionalSkip.conditionField}, ${conditionalSkip.valueField}: ${conditionalSkip.valueField}, playerApiLevel: playerApiLevel, playerProfiles: playerProfiles)"
                )
            }
            val bits = f.bits
            if (bits != null && f.unpackBits) {
                val rawVar = "raw_${f.name}"
                w.line("let $rawVar = try buffer.readInt()")
                if (f.mustBeZeroBits != null) {
                    val badBits = swiftReservedBits(rawVar, f.name)
                    w.block("if $badBits") {
                        line(
                            "throw WireError.reservedBitsSet(type: \"$ownerName\", field: \"${f.name}\")"
                        )
                    }
                }
                for (b in bits) {
                    w.line(
                        "let ${b.name} = ${swiftExtract(rawVar, f.name, b)}"
                    )
                    emitSwiftStrictEnumCheck(
                        w,
                        ownerName,
                        b.name,
                        b.name,
                        b.strictEnum,
                        b.enumValues,
                    )
                }
                continue
            }

            val isLocalDerived = f.derivedFrom != null
            val isNullable =
                !isLocalDerived &&
                    f.presentIf != null &&
                    !f.type.endsWith("[]") &&
                    f.defaultValue == null

            if (f.presentIf != null) {
                val cond = swiftCondition(f.presentIf)
                val swiftType = mapToSwiftType(f.type, isNullable)
                w.line("let ${f.name}: $swiftType")
                w.block("if $cond", close = null) {
                    if (f.type.endsWith("[]")) {
                        emitSwiftArrayRead(this, ownerName, f, "${f.name}Tmp")
                        line("${f.name} = ${f.name}Tmp")
                    } else if (hasSwiftScalarValidations(f)) {
                        line("let parsed = try ${mapToSwiftFieldReadExpr(f)}")
                        emitSwiftScalarValidations(this, ownerName, f, "parsed")
                        line("${f.name} = parsed")
                    } else {
                        line("${f.name} = try ${mapToSwiftFieldReadExpr(f)}")
                    }
                }
                w.block("} else") {
                    line(
                        "${f.name} = ${if (!isNullable && f in defaultFields(fields)) defaultRef(ownerName, f) else mapToSwiftDefault(f.type, isNullable, f.defaultValue)}"
                    )
                }
            } else if (f.type.endsWith("[]")) {
                emitSwiftArrayRead(w, ownerName, f, f.name)
            } else {
                w.line("let ${f.name} = try ${mapToSwiftFieldReadExpr(f)}")
                emitSwiftScalarValidations(w, ownerName, f, f.name)
            }
        }

        if (sparseParameters != null) {
            for (sp in sparseParameters) {
                w.line("var ${sp.name}: ${mapToSwiftType(sp.type, true)} = nil")
            }
            val effectiveCountType = sparseCountType ?: "ushort"
            val effectiveKeyType = sparseKeyType ?: "ubyte"
            when (effectiveCountType) {
                "int" -> {
                    w.line("let sparseCount = Int(try buffer.readInt())")
                    w.block("guard sparseCount >= 0 else") {
                        line(
                            "throw WireError.invalidLength(type: \"$ownerName\", field: \"sparseParameters\", length: sparseCount)"
                        )
                    }
                }
                "short" -> {
                    w.line("let sparseCount = Int(try buffer.readShort())")
                    w.block("guard sparseCount >= 0 else") {
                        line(
                            "throw WireError.invalidLength(type: \"$ownerName\", field: \"sparseParameters\", length: sparseCount)"
                        )
                    }
                }
                "byte" -> {
                    w.line("let sparseCount = Int(Int8(bitPattern: try buffer.readByte()))")
                    w.block("guard sparseCount >= 0 else") {
                        line(
                            "throw WireError.invalidLength(type: \"$ownerName\", field: \"sparseParameters\", length: sparseCount)"
                        )
                    }
                }
                "ubyte" -> w.line("let sparseCount = Int(try buffer.readByte())")
                else -> w.line("let sparseCount = Int(UInt16(bitPattern: try buffer.readShort()))")
            }
            // LOCAL PATCH (rc-players): a key and at least one byte of value, by name.
            val minEntryBytes = "(${sparseKeyBytes(effectiveKeyType)} + MemoryLayout<UInt8>.size)"
            w.block("guard sparseCount <= buffer.remaining / $minEntryBytes else") {
                line(
                    "throw WireError.lengthExceedsBuffer(type: \"$ownerName\", field: \"sparseParameters\", length: sparseCount)"
                )
            }
            w.block("for _ in 0..<sparseCount") {
                when (effectiveKeyType) {
                    "int" -> line("let paramId = Int(try buffer.readInt())")
                    "ushort" ->
                        line("let paramId = Int(UInt16(bitPattern: try buffer.readShort()))")
                    "short" -> line("let paramId = Int(try buffer.readShort())")
                    "byte" -> line("let paramId = Int(Int8(bitPattern: try buffer.readByte()))")
                    else -> line("let paramId = Int(try buffer.readByte())")
                }
                swiftSwitch("paramId") {
                    for (sp in sparseParameters) {
                        swiftCase("case SparseParameterID.${sp.name}") {
                            if (sp.type.endsWith("[]")) {
                                val synField =
                                    SchemaField(
                                        name = sp.name,
                                        type = sp.type,
                                        description = sp.description,
                                        enumValues = null,
                                        lengthType = sp.lengthType ?: "ushort",
                                    )
                                emitSwiftArrayRead(this, ownerName, synField, "${sp.name}Tmp")
                                line("${sp.name} = ${sp.name}Tmp")
                            } else {
                                line("${sp.name} = try ${mapToSwiftReadExpr(sp.type)}")
                            }
                        }
                    }
                    swiftCase("default") {
                        line(
                            "throw WireError.unknownSparseParameter(type: \"$ownerName\", id: paramId)"
                        )
                    }
                }
            }
        }

        val args = props.joinToString(", ") { "${it.name}: ${it.name}" }
        w.line("return $ownerName($args)")
    }

    private fun emitSwiftStrictEnumCheck(
        w: CodeWriter,
        ownerName: String,
        fieldName: String,
        varExpr: String,
        strictEnum: Boolean,
        enumValues: Map<String, Int>?,
    ) {
        if (strictEnum && !enumValues.isNullOrEmpty()) {
            // LOCAL PATCH (rc-players): the allowed values by name, as the struct defines them.
            val fields = ownerFields(ownerName)
            val allowed =
                enumValues.entries
                    .sortedBy { it.value }
                    .distinctBy { it.value }
                    .joinToString(", ") { enumRef(ownerName, fields, it.key, it.value) }
            w.swiftSwitch(varExpr) {
                swiftCase("case $allowed") { line("break") }
                swiftCase("default") {
                    line(
                        "throw WireError.invalidEnumValue(type: \"$ownerName\", field: \"$fieldName\")"
                    )
                }
            }
        }
    }

    private fun emitSwiftArrayRead(
        w: CodeWriter,
        ownerName: String,
        f: SchemaField,
        targetVar: String,
    ) {
        val lenVar = "_${f.name}Count"
        if (f.countFrom != null) {
            w.line("let $lenVar = Int(${f.countFrom})")
        } else {
            when (f.effectiveLengthType) {
                "int" -> w.line("let $lenVar = Int(try buffer.readInt())")
                "ushort" -> w.line("let $lenVar = Int(UInt16(bitPattern: try buffer.readShort()))")
                "ubyte" -> w.line("let $lenVar = Int(try buffer.readByte())")
                "byte" -> w.line("let $lenVar = Int(Int8(bitPattern: try buffer.readByte()))")
                else -> w.line("let $lenVar = Int(try buffer.readShort())")
            }
        }
        val elemType = f.type.removeSuffix("[]")
        val elemMinBytes = elementBytes(elemType)
        w.block("guard $lenVar >= 0 else") {
            line(
                "throw WireError.invalidLength(type: \"$ownerName\", field: \"${f.name}\", length: $lenVar)"
            )
        }
        if (f.minLength != null && f.minLength > 0) {
            w.block("guard $lenVar >= ${f.minLength} else") {
                line(
                    "throw WireError.lengthBelowMinimum(type: \"$ownerName\", field: \"${f.name}\", length: $lenVar)"
                )
            }
        }
        if (f.maxLength != null) {
            w.block("guard $lenVar <= ${limitRef(f)} else") {
                line(
                    "throw WireError.lengthExceedsLimit(type: \"$ownerName\", field: \"${f.name}\", length: $lenVar, limit: ${limitRef(f)})"
                )
            }
        }
        w.block("guard $lenVar <= buffer.remaining / $elemMinBytes else") {
            line(
                "throw WireError.lengthExceedsBuffer(type: \"$ownerName\", field: \"${f.name}\", length: $lenVar)"
            )
        }
        val swiftElemType = mapToSwiftType(elemType, false)
        w.line("var $targetVar = [$swiftElemType]()")
        // LOCAL PATCH (rc-players): `Swift.min`. Unqualified, `min` resolves to the operation's own
        // `min` field where it has one (`TouchExpression`, `HeightIn`, `WidthIn`), and upstream's
        // output fails to compile there ("cannot call value of non-function type 'Float'").
        w.line("$targetVar.reserveCapacity(Swift.min($lenVar, WireLimits.MAX_INITIAL_CAPACITY))")
        w.block("for _ in 0..<$lenVar") {
            line("$targetVar.append(try ${mapToSwiftReadExpr(elemType)})")
        }
    }

    private fun emitSwiftWriteBody(
        w: CodeWriter,
        ownerName: String,
        fields: List<SchemaField>,
        sparseParameters: List<SchemaSparseParam>?,
        props: List<AstProperty>,
        sparseCountType: String? = null,
        sparseKeyType: String? = null,
        conditionalSkip: SchemaConditionalSkip? = null,
    ) {
        val propByName = props.associateBy { it.name }
        val localVars = mutableSetOf<String>()

        for (f in fields) {
            val bits = f.bits
            if (bits != null && f.unpackBits) {
                val terms = mutableListOf<Pair<String, SchemaBitField>>()
                for (b in bits) {
                    if (b.derivedFrom != null) {
                        val expr = derivedExprToSwift(DerivedExpr.parse(b.derivedFrom))
                        w.line("let ${b.name}: Int32 = $expr")
                        localVars.add(b.name)
                        terms.add(b.name to b)
                    } else {
                        terms.add(b.name to b)
                    }
                }
                val packed = swiftPack(f.name, terms)
                w.line("buffer.writeInt($packed)")
                continue
            }

            if (f.derivedFrom != null) {
                val expr = derivedExprToSwift(DerivedExpr.parse(f.derivedFrom))
                if (f.presentIf != null) {
                    val cond =
                        swiftCondition(f.presentIf)
                    w.block("if $cond") { line(mapToSwiftDerivedWrite(f.type, expr)) }
                } else {
                    w.line("let ${f.name}: Int32 = $expr")
                    localVars.add(f.name)
                    w.line(mapToSwiftDerivedWrite(f.type, f.name))
                }
                continue
            }

            val isNullable = propByName[f.name]?.isNullable == true
            if (conditionalSkip != null && f.name == conditionalSkip.lengthField) {
                w.line(
                    "buffer.writeInt(${conditionalSkip.payloadField} != nil ? Int32(${conditionalSkip.payloadField}!.count) : ${f.name})"
                )
                continue
            }
            if (conditionalSkip != null && f.name == conditionalSkip.payloadField) {
                w.block("if let val = ${f.name}") { line("buffer.writeBytes(val)") }
                continue
            }
            if (f.presentIf != null) {
                val cond = swiftCondition(f.presentIf)
                w.block("if $cond") {
                    if (isNullable) {
                        block("guard let val = ${f.name} else") {
                            line(
                                "throw WireError.missingField(type: \"$ownerName\", field: \"${f.name}\")"
                            )
                        }
                        emitSwiftFieldWrite(this, f, "val")
                    } else {
                        emitSwiftFieldWrite(this, f, f.name)
                    }
                }
            } else {
                emitSwiftFieldWrite(w, f, f.name)
            }
        }

        if (sparseParameters != null) {
            w.line("var sparseCount: Int32 = 0")
            for (sp in sparseParameters) {
                w.line("if ${sp.name} != nil { sparseCount += 1 }")
            }
            when (sparseCountType ?: "ushort") {
                "int" -> w.line("buffer.writeInt(sparseCount)")
                "ubyte",
                "byte" -> w.line("buffer.writeByte(UInt8(truncatingIfNeeded: sparseCount))")
                else -> w.line("buffer.writeShort(Int16(truncatingIfNeeded: sparseCount))")
            }
            val effectiveKeyType = sparseKeyType ?: "ubyte"
            for (sp in sparseParameters) {
                w.block("if let val = ${sp.name}") {
                    when (effectiveKeyType) {
                        "int" -> line("buffer.writeInt(Int32(SparseParameterID.${sp.name}))")
                        "ushort",
                        "short" ->
                            line(
                                "buffer.writeShort(Int16(truncatingIfNeeded: SparseParameterID.${sp.name}))"
                            )
                        else ->
                            line(
                                "buffer.writeByte(UInt8(truncatingIfNeeded: SparseParameterID.${sp.name}))"
                            )
                    }
                    val synField =
                        SchemaField(
                            name = sp.name,
                            type = sp.type,
                            description = sp.description,
                            enumValues = null,
                            lengthType = sp.lengthType ?: "ushort",
                        )
                    emitSwiftFieldWrite(this, synField, "val")
                }
            }
        }
    }

    private fun emitSwiftFieldWrite(w: CodeWriter, f: SchemaField, varExpr: String) {
        if (f.type.endsWith("[]")) {
            if (f.countFrom == null) {
                when (f.effectiveLengthType) {
                    "int" -> w.line("buffer.writeInt(Int32($varExpr.count))")
                    "ubyte",
                    "byte" -> w.line("buffer.writeByte(UInt8(truncatingIfNeeded: $varExpr.count))")
                    else -> w.line("buffer.writeShort(Int16(truncatingIfNeeded: $varExpr.count))")
                }
            }
            val elemType = f.type.removeSuffix("[]")
            w.block("for item in $varExpr") { line(mapToSwiftWriteExpr(elemType, "item")) }
        } else if (f.type == "bytes" && f.countFrom != null) {
            w.line("buffer.writeBytes($varExpr)")
        } else {
            w.line(mapToSwiftWriteExpr(f.type, varExpr))
        }
    }

    private fun mapToSwiftFieldReadExpr(f: SchemaField): String {
        if (f.type == "bytes" && f.countFrom != null) {
            return "buffer.readBytes(count: Int(${f.countFrom}))"
        }
        return mapToSwiftReadExpr(f.type, limitRef(f))
    }

    private inline fun CodeWriter.swiftSwitch(expr: String, body: CodeWriter.() -> Unit) {
        line("switch $expr {")
        body()
        line("}")
    }

    private inline fun CodeWriter.swiftCase(label: String, body: CodeWriter.() -> Unit) {
        line("$label:")
        indent(body)
    }

    private fun derivedExprToSwift(expr: DerivedExpr): String {
        val target = expr.targetName
        return when (expr) {
            is DerivedExpr.LengthOf -> "Int32($target.count)"
            is DerivedExpr.PresentOf -> "($target != nil ? 1 : 0)"
            is DerivedExpr.NonEmptyOf -> "(!$target.isEmpty ? 1 : 0)"
        }
    }

    private fun mapToSwiftDerivedWrite(type: String, int32Expr: String): String =
        when (type) {
            "short" -> "buffer.writeShort(Int16(truncatingIfNeeded: $int32Expr))"
            "byte" -> "buffer.writeByte(UInt8(truncatingIfNeeded: $int32Expr))"
            else -> "buffer.writeInt($int32Expr)"
        }

    private fun mapToSwiftType(type: String, isNullable: Boolean): String {
        val base =
            if (type.endsWith("[]")) {
                "[${mapToSwiftType(type.removeSuffix("[]"), false)}]"
            } else {
                when (type) {
                    "int",
                    "int_id",
                    "color" -> "Int32"
                    "short" -> "Int16"
                    "byte" -> "UInt8"
                    "long" -> "Int64"
                    "float",
                    "float_or_id" -> "Float"
                    "boolean" -> "Bool"
                    "string" -> "String"
                    "bytes" -> "[UInt8]"
                    else -> if (schema.structs.containsKey(type)) type else "Int32"
                }
            }
        return if (isNullable) "$base?" else base
    }

    private fun mapToSwiftDefault(
        type: String,
        isNullable: Boolean,
        explicitDefault: String?,
    ): String {
        if (isNullable) return "nil"
        if (explicitDefault != null) {
            return when (type) {
                "float",
                "float_or_id" ->
                    if (explicitDefault.contains('.')) explicitDefault else "$explicitDefault.0"
                else -> explicitDefault
            }
        }
        if (type.endsWith("[]")) return "[]"
        return when (type) {
            "int",
            "int_id",
            "color",
            "short",
            "byte" -> "0"
            "long" -> "0"
            "float",
            "float_or_id" -> "0.0"
            "boolean" -> "false"
            "string" -> "\"\""
            "bytes" -> "[]"
            else -> if (schema.structs.containsKey(type)) "$type()" else "0"
        }
    }

    private fun mapToSwiftReadExpr(type: String, maxLength: String? = null): String =
        when (type) {
            "int",
            "int_id",
            "color" -> "buffer.readInt()"
            "short" -> "buffer.readShort()"
            "byte" -> "buffer.readByte()"
            "long" -> "buffer.readLong()"
            "float",
            "float_or_id" -> "buffer.readFloat()"
            "boolean" -> "buffer.readBoolean()"
            "string" ->
                if (maxLength != null) "buffer.readUTF8(maxLength: $maxLength)"
                else "buffer.readUTF8()"
            "bytes" ->
                if (maxLength != null) "buffer.readBuffer(maxLength: $maxLength)"
                else "buffer.readBuffer()"
            else ->
                if (schema.structs.containsKey(type)) "$type.read(from: &buffer)"
                else "buffer.readInt()"
        }

    private fun mapToSwiftWriteExpr(type: String, varName: String): String =
        when (type) {
            "int",
            "int_id",
            "color" -> "buffer.writeInt($varName)"
            "short" -> "buffer.writeShort($varName)"
            "byte" -> "buffer.writeByte($varName)"
            "long" -> "buffer.writeLong($varName)"
            "float",
            "float_or_id" -> "buffer.writeFloat($varName)"
            "boolean" -> "buffer.writeBoolean($varName)"
            "string" -> "buffer.writeUTF8($varName)"
            "bytes" -> "buffer.writeBuffer($varName)"
            else ->
                if (schema.structs.containsKey(type)) "try $varName.write(to: &buffer)"
                else "buffer.writeInt($varName)"
        }

    companion object {
        private val DECLARED_CONSTANT = Regex("""static let ([A-Z][A-Z0-9]*(?:_[A-Z0-9]+)+|[A-Z]{2,}[0-9]*)\b""")
        private val STRING_LITERAL = Regex(""""(?:[^"\\]|\\.)*"""")
        private val SWIFT_KEYWORDS = setOf("default", "case", "in", "is", "as", "repeat", "return")

        /** `DOC_WIDTH` → `docWidth`, `VERSION_1` → `version1`, `RECTANGLE` → `rectangle`. */
        private fun lowerCamel(name: String): String {
            val parts = name.lowercase().split('_').filter { it.isNotEmpty() }
            val joined = parts.first() + parts.drop(1).joinToString("") { it.replaceFirstChar(Char::uppercase) }
            return if (joined in SWIFT_KEYWORDS) "`$joined`" else joined
        }

        /** Renames every declared SCREAMING_SNAKE constant, and each use of it, outside string literals. */
        internal fun lowerCamelConstants(swift: String): String {
            val names = DECLARED_CONSTANT.findAll(swift).map { it.groupValues[1] }.toSet()
            if (names.isEmpty()) return swift
            val use = Regex("""(?<![\w`])(${names.sortedByDescending { it.length }.joinToString("|")})(?![\w`])""")
            return swift.lines().joinToString("\n") { line ->
                val out = StringBuilder()
                var last = 0
                for (literal in STRING_LITERAL.findAll(line)) {
                    out.append(use.replace(line.substring(last, literal.range.first)) { lowerCamel(it.value) })
                    out.append(literal.value)
                    last = literal.range.last + 1
                }
                out.append(use.replace(line.substring(last)) { lowerCamel(it.value) })
                out.toString()
            }
        }

        const val WIRE_EXPRESSION_CONSTANTS: String = "WireExpressionConstants"
        /** Upstream's cap on the room an array read reserves up front. */
        const val MAX_INITIAL_CAPACITY: Int = 4096

        fun toCamelCase(name: String): String = name.replaceFirstChar { it.lowercaseChar() }
    }
}
